"""Send a reconciliation workbook through Amazon SES SMTP."""

from __future__ import annotations

import re
import smtplib
from email.message import EmailMessage
from pathlib import Path

from app.core.config import get_settings
from app.modules.webtechAIAgent.reconciliation.entity_normalization import norm
from app.modules.webtechAIAgent.reconciliation.excel_export import OUT_DIR

SUBJECT = "Excel Report Generated by WebTechAgent AI Assistant"
BODY = (
    "Please find attached the Excel file generated by the WebTechAgent AI Assistant "
    "for your review."
)
EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")


def email_addresses(text: str) -> list[str]:
    found: list[str] = []
    seen: set[str] = set()
    for match in EMAIL_RE.findall(text or ""):
        address = match.strip().lower()
        if address in seen:
            continue
        seen.add(address)
        found.append(address)
    return found


def without_emails(text: str) -> str:
    return EMAIL_RE.sub(" ", text or "")


def wants_excel_mail(text: str) -> bool:
    hay = norm(text)
    if not email_addresses(text):
        return False
    words = set(hay.split())
    return bool(words & {"mail", "email", "bhej", "bhejo", "send", "kr", "karo"}) or "kar do" in hay


def _allowed_file(path: Path) -> bool:
    try:
        resolved = path.resolve()
        root = OUT_DIR.resolve()
    except OSError:
        return False
    return resolved.is_file() and resolved.suffix.lower() == ".xlsx" and resolved.is_relative_to(root)


def send_excel_files(recipients: list[str], paths: list[str]) -> str:
    settings = get_settings()
    host = settings.ses_smtp_host.strip()
    user = settings.ses_smtp_user.strip()
    password = settings.ses_smtp_pass.strip()
    if not host or not user or not password:
        return "Mail abhi configured nahi hai. SES SMTP host, user, aur password chahiye."
    files = [Path(item) for item in paths if _allowed_file(Path(item))]
    if not files:
        return "Bhejne ke liye Excel file nahi mili. Pehle dark store ka Excel banao."
    if not recipients:
        return "Email address likho, jaise manoj@gramik.in."

    message = EmailMessage()
    from_email = settings.ses_from_email.strip() or "noreply@gramik.in"
    from_name = settings.ses_from_name.strip() or "WebTechAgent AI Assistant"
    message["From"] = f"{from_name} <{from_email}>"
    message["To"] = ", ".join(recipients)
    message["Subject"] = SUBJECT
    message.set_content(BODY)
    for file_path in files:
        message.add_attachment(
            file_path.read_bytes(),
            maintype="application",
            subtype="vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            filename=file_path.name,
        )
    try:
        with smtplib.SMTP(host, settings.ses_smtp_port, timeout=30) as smtp:
            smtp.starttls()
            smtp.login(user, password)
            smtp.send_message(message)
    except (OSError, TimeoutError, smtplib.SMTPException) as exc:
        return f"Mail nahi gaya: {exc}"
    names = ", ".join(path.name for path in files)
    return f"Excel {names} bhej diya: {', '.join(recipients)}."
